-- B6a: Carpool posts, booking requests, contracts and sessions.
-- * carpool_posts: close_reason (CLOSED is final) and paused_at ("Stop new
--   bookings" pauses a post without closing it).
-- * activities.closure_reason: POST_CHANGED, POST_REMOVED (pending booking
--   requests rejected when the rider edits or removes the post).
-- * notifications: CARPOOL_AGREE_REQUESTED.
-- AlterTable
ALTER TABLE `activities` MODIFY `closure_reason` ENUM('EXPIRED_UNACCEPTED', 'NOT_MARKED_TIMEOUT', 'AUTO_COMPLETED', 'DELETED_BY_CREATOR', 'BOOKING_REJECTED', 'SEAT_HOLD_EXPIRED', 'ACCOUNT_MODERATED', 'ADMIN_REMOVED', 'DISPUTE_RESOLVED', 'POST_CHANGED', 'POST_REMOVED') NULL;

-- AlterTable
ALTER TABLE `carpool_posts` ADD COLUMN `close_reason` ENUM('REMOVED_BY_RIDER', 'ENDED', 'ACCOUNT_MODERATED', 'ADMIN_REMOVED') NULL,
    ADD COLUMN `paused_at` DATETIME(3) NULL;

-- AlterTable
ALTER TABLE `notifications` MODIFY `type` ENUM('REQUEST_ACCEPTED', 'SEAT_BOOKED', 'CARPOOL_BOOKING_REQUESTED', 'CARPOOL_BOOKING_ACCEPTED', 'CARPOOL_BOOKING_REJECTED', 'CARPOOL_CONTRACT_CREATED', 'CARPOOL_SESSION_REMINDER', 'ACTIVITY_REMINDER', 'COMPLETION_REQUESTED', 'AUTO_COMPLETED', 'AUTO_CLOSED_NOT_MARKED', 'ACTIVITY_CANCELLED', 'DISPUTE_OPENED', 'DISPUTE_UPDATED', 'DISPUTE_RESOLVED', 'NEW_CHAT_MESSAGE', 'SUB_AREA_NEW_REQUEST', 'STUDENT_VERIFICATION_RESULT', 'RIDER_VERIFICATION_RESULT', 'REQUEST_EXPIRED', 'CARPOOL_PAYMENT_DUE', 'REPORT_UPDATE', 'SUPPORT_UPDATE', 'ANNOUNCEMENT', 'ACCOUNT_STATUS_CHANGED', 'PASSWORD_RESET_REQUESTED', 'PASSWORD_CHANGED', 'LICENCE_EXPIRY_REMINDER', 'PARTICIPANT_ACCOUNT_LOCKED', 'RIDER_ACCESS_CHANGED', 'REVIEW_PUBLISHED', 'FOOD_ORDER_TO_CONFIRM', 'FOOD_BUDGET_APPROVAL_REQUESTED', 'FOOD_BUDGET_APPROVAL_DECIDED', 'CARPOOL_AGREE_REQUESTED') NOT NULL;
